pragma solidity >=0.8.0;
contract EventOrderPackM2 {
    event Mark(uint8 indexed tag, string indexed s, bytes b);
    event Tick(uint8 indexed n);
    uint8 public flag;
    string public s1;
    bytes public b1;
    function mix() external {
        emit Mark(1, "a", hex"01");
        emit Tick(10);
        emit Mark(2, "bc", hex"");
        emit Mark(3, "def", hex"0102");
        emit Tick(11);
        emit Mark(4, "ghij", hex"03");
        flag = 4;
        s1 = "bc";
        b1 = hex"0102";
    }
    function getAll() external view returns (uint8, string memory, bytes memory) {
        return (flag, s1, b1);
    }
}
